import {mountExperiment} from '../model-kit/session.js';
import {attachCardDrag} from '../shared/drag.js';
import {definition} from '../../../embed/definitions/lab-possibilities.js';
import {TASKS,DEMANDS,PLANS,simulate,compare,moveTask,describe} from './model.js';
const e=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=id=>TASKS.find(t=>t.id===id).name;
const names=tasks=>tasks.map(t=>t.name).join(', ')||'None';
function render(s,{pinned}){const r=simulate(s),b=compare(s,pinned);
const task=t=>`<article class="poss-task ${t.status}" data-drag-id="${t.id}"><div class="poss-task-heading"><h3>${e(t.name)}</h3><span class="poss-state">${t.status}${t.wanted?' · needed':''}</span></div><p>${t.needs.length?'Needs '+t.needs.map(id=>e(name(id))).join(' + '):'No prerequisites'} · ${t.cost} effort</p><div class="poss-actions"><button type="button" data-drag-handle id="drag-${t.id}" aria-label="Drag ${e(t.name)} into the work sequence">↕ Move</button><button type="button" data-add="${t.id}" id="add-${t.id}" ${s.plan.includes(t.id)?'disabled':''}>${s.plan.includes(t.id)?'In sequence':'Add to sequence'}</button></div></article>`;
return `<section class="poss-situation" aria-label="External situation"><label for="poss-demand">Demand after this work<select id="poss-demand">${Object.entries(DEMANDS).map(([id,d])=>`<option value="${id}" ${s.demand===id?'selected':''}>${e(d.name)}</option>`).join('')}</select></label><label for="poss-budget">Available effort<input type="number" id="poss-budget" min="1" max="30" step="1" value="${s.budget}"></label><p>${e(DEMANDS[s.demand].detail)}</p></section>
<div class="poss-verdict"><strong>${r.served.length} / ${DEMANDS[s.demand].wanted.length}</strong><span>needed services delivered<br><small>${r.spent} of ${s.budget} effort used · ${r.remaining} left</small></span></div>
<div class="poss-workspace"><section class="poss-landscape" aria-labelledby="landscape-title"><h2 id="landscape-title">Change what is possible</h2><p class="poss-intro">Add work to the sequence. Prerequisites describe what has to exist first.</p><div class="poss-lanes"><section><h3 class="poss-lane-title">Enabling conditions</h3>${r.landscape.filter(t=>t.kind==='enabler').map(task).join('')}</section><section><h3 class="poss-lane-title">Services people can use</h3>${r.landscape.filter(t=>t.kind==='delivery').map(task).join('')}</section></div></section>
<section class="poss-sequence" aria-labelledby="sequence-title"><h2 id="sequence-title">Your work sequence</h2><p class="poss-intro">Drag to insert before a step, or use Add and Earlier / Later. Work runs top to bottom.</p><div class="poss-presets"><button type="button" id="poss-direct" data-plan="direct">Deliver available work</button><button type="button" id="poss-enable" data-plan="enable">Open new possibilities</button><button type="button" id="poss-empty" data-plan="empty">Empty sequence</button></div>
<ol class="poss-plan">${r.trace.map((t,i)=>`<li class="poss-step ${t.status}" data-drag-id="${t.id}" data-drop-id="${i}"><div class="poss-step-top"><span class="poss-step-number">${i+1}</span><h3>${e(t.name)}</h3><button type="button" data-drag-handle id="plan-drag-${t.id}" aria-label="Drag ${e(t.name)} to reorder">↕</button></div><p><strong>${t.status}</strong> · ${t.cost} effort<br>${e(t.reason)}</p><small>${t.spent} / ${s.budget} effort used after this step</small><div class="poss-actions"><button type="button" id="earlier-${t.id}" data-move="${t.id}" data-index="${i-1}" ${i===0?'disabled':''} aria-label="Move ${e(t.name)} earlier">Earlier</button><button type="button" id="later-${t.id}" data-move="${t.id}" data-index="${i+1}" ${i===r.trace.length-1?'disabled':''} aria-label="Move ${e(t.name)} later">Later</button><button type="button" id="remove-${t.id}" data-remove="${t.id}" aria-label="Remove ${e(t.name)} from sequence">Remove</button></div></li>`).join('')}</ol><div class="poss-drop" data-drop-id="${s.plan.length}">Drop a task here to put it last${s.plan.length?'':' · or use Add to sequence'}</div></section></div>
<section class="experiment-output" aria-labelledby="poss-outcome"><h2 id="poss-outcome">What this sequence leaves possible</h2><div class="poss-outcomes"><p><strong>Delivered and needed</strong>${e(names(r.served))}</p><p><strong>Still needed</strong>${e(names(r.unmet))}</p><p><strong>Reachable next</strong>${e(names(r.reachable))}<small>Prerequisites met; still needs effort.</small></p></div>${b?`<h3>Pinned sequence under the same situation</h3><p>Both sequences use the current demand, budget and effort estimates. Only work and order differ.</p><div class="table-scroll"><table><thead><tr><th>Sequence</th><th>Needed services delivered</th><th>Effort used</th><th>Reachable next</th></tr></thead><tbody><tr><th>Current</th><td>${r.served.length}</td><td>${r.spent}</td><td>${r.reachable.length}</td></tr><tr><th>Pinned</th><td>${b.served.length}</td><td>${b.spent}</td><td>${b.reachable.length}</td></tr></tbody></table></div><p class="poss-intro">Pinned order: ${pinned.plan.map(id=>e(name(id))).join(' → ')||'Empty'}.</p>`:''}</section>
<details id="poss-assumptions"><summary>Challenge the effort and mechanism</summary><div class="poss-costs">${TASKS.map(t=>`<label for="cost-${t.id}">${e(t.name)}<input id="cost-${t.id}" type="number" min="1" max="10" step="1" data-cost="${t.id}" value="${s.costs[t.id]}"></label>`).join('')}</div><p>One effort unit is whatever unit you choose consistently. Tasks are indivisible, run once in order and do not expire. A task with missing prerequisites or insufficient budget is skipped without spending effort; it is not retried. Reorder it to try again.</p><p>Needed services are distinct needs, not money, utility or an ROI score. Reachable work can still be unaffordable. The dependency graph is fictional and fixed; effort and demand are challengeable. There is no uncertainty or parallel work.</p><p>Try pinning “Deliver available work”, switching to “Open new possibilities”, then changing demand. Enabling work is useful only when the opened services are needed and affordable.</p><p>Inspired by John Cutler’s <a href="https://cutlefish.substack.com/p/tbm-1652-can-do-vs-should-do">Can Do vs. Should Do</a>.</p></details>`;
}
function bind({root,state,change}){
const update=(edit,message)=>{const next=structuredClone(state);edit(next);change(next,message);};
const click=event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.add)change(moveTask(state,b.dataset.add,state.plan.length),'Task added to the sequence.');if(b.dataset.plan)update(s=>{s.plan=[...PLANS[b.dataset.plan]];},'Example sequence loaded.');if(b.dataset.move)change(moveTask(state,b.dataset.move,Number(b.dataset.index)),'Task reordered.');if(b.dataset.remove)update(s=>{s.plan=s.plan.filter(id=>id!==b.dataset.remove);},'Task removed from the sequence.');};
const input=event=>{const el=event.target;if(el.id==='poss-demand')update(s=>{s.demand=el.value;},'Demand changed. Both sequences replay the same situation.');if(el.id==='poss-budget')update(s=>{s.budget=Number(el.value);},'Effort budget changed.');if(el.dataset.cost)update(s=>{s.costs[el.dataset.cost]=Number(el.value);},'Effort estimate changed.');};
root.addEventListener('click',click);root.addEventListener('change',input);
const drag=attachCardDrag({root,onDrop:({itemId,dropId})=>{const index=Number(dropId),from=state.plan.indexOf(itemId);change(moveTask(state,itemId,from>=0&&from<index?index-1:index),'Task moved in the sequence.');}});
return()=>{drag();root.removeEventListener('click',click);root.removeEventListener('change',input);};
}
await mountExperiment({route:'possibilities',definition,render,bind,describe});
